SELECT (v.n = s.n AND v.pieces = s.pieces AND v.rows_in_file = s.n AND v.basis_ok AND v.receipts_zero) AS ok, v.n AS view_rows, s.n AS count_rows, v.pieces AS view_pieces, s.pieces AS count_pieces FROM (SELECT COUNT(*) AS n, SUM(opening_pieces) AS pieces, COUNT(*) FILTER (WHERE in_stock_file) AS rows_in_file, bool_and(opening_basis = 'count') AS basis_ok, SUM(expected_receipt_pieces) = 0 AS receipts_zero FROM stock_opening_v WHERE cycle = DATE '2026-03-01') v, (SELECT COUNT(*) AS n, SUM(t.stock_pieces) AS pieces FROM (SELECT inv.product_key, CASE WHEN pd_pack.pack_size ~ '^[0-9]+(\.[0-9]+)?$' AND pd_pack.pack_size::numeric > 0 THEN SUM(inv.quantity_on_hand) * pd_pack.pack_size::numeric + COALESCE(SUM(inv.quantity_pieces), 0) END AS stock_pieces FROM inventory_fact_real inv JOIN product_dimension pd_pack ON pd_pack.product_key = inv.product_key WHERE inv._period = '2026-02' AND inv.principal = 'unilever' GROUP BY inv.product_key, pd_pack.pack_size) t) s
